/**
 * @fileoverview Permission policy enforcement for tool execution.
 *
 * Provides the PermissionPolicy class which decides whether a tool may execute
 * given the current execution environment and the tool's declared policy.
 *
 * @module security/permissions
 */

import type { ExecutionEnvironment, ToolPermission, ToolPolicy } from '../tools/types.js';

// =============================================================================
// Types
// =============================================================================

/** Result of a permission check. */
export interface PermissionCheckResult {
  allowed: boolean;
  reason?: string;
}

// =============================================================================
// Permission Policy
// =============================================================================

/**
 * Evaluates whether a tool is permitted to run given the current execution
 * environment and a set of granted permissions.
 */
export class PermissionPolicy {
  private environment: ExecutionEnvironment;
  private grantedPermissions: Set<ToolPermission>;

  constructor(
    environment: ExecutionEnvironment = 'local',
    grantedPermissions: ToolPermission[] = ['read', 'write', 'execute'],
  ) {
    this.environment = environment;
    this.grantedPermissions = new Set(grantedPermissions);
  }

  /** Returns the current execution environment. */
  getEnvironment(): ExecutionEnvironment {
    return this.environment;
  }

  /** Updates the execution environment at runtime. */
  setEnvironment(env: ExecutionEnvironment): void {
    this.environment = env;
  }

  /** Grants a permission level. */
  grant(permission: ToolPermission): void {
    this.grantedPermissions.add(permission);
  }

  /** Revokes a permission level. */
  revoke(permission: ToolPermission): void {
    this.grantedPermissions.delete(permission);
  }

  /** Returns currently granted permissions. */
  getGrantedPermissions(): ToolPermission[] {
    return Array.from(this.grantedPermissions);
  }

  /**
   * Checks whether a tool with the given policy is allowed to execute.
   *
   * Enforcement order:
   * 1. Local-only tools are blocked in cloud environments.
   * 2. The tool's required permission must be granted.
   */
  check(toolName: string, policy: ToolPolicy): PermissionCheckResult {
    // Local-only enforcement
    if (policy.localOnly && this.environment !== 'local') {
      return {
        allowed: false,
        reason: `Tool '${toolName}' is local-only and cannot run in '${this.environment}' environment`,
      };
    }

    // Permission enforcement
    if (!this.grantedPermissions.has(policy.permission)) {
      return {
        allowed: false,
        reason: `Tool '${toolName}' requires '${policy.permission}' permission which is not granted`,
      };
    }

    return { allowed: true };
  }
}

