/**
 * @fileoverview Tool Manager — lifecycle, security, and execution context.
 *
 * Wraps the existing ToolRegistry with:
 * - Enable / disable per tool
 * - Usage and error rate tracking
 * - Local-only policy enforcement via PermissionPolicy
 * - Tool discovery (scans src/tools/ for custom tool files)
 *
 * @module tools/manager
 */

import { ToolRegistry, getToolRegistry, type OrchestratorTool } from './registry.js';
import { PermissionPolicy } from '../security/permissions.js';
import { logger } from '../utils/logger.js';
import type {
  ToolResult,
  ToolContext,
  ExecutionEnvironment,
  ToolPermission,
  ToolPolicy,
} from './types.js';
import { DangerLevel } from './types.js';
import fs from 'fs';
import path from 'path';

// ============================================================================
// Usage Statistics
// ============================================================================

/** Per-tool usage counters. */
export interface ToolUsageStats {
  invocations: number;
  successes: number;
  failures: number;
  totalDurationMs: number;
}

// ============================================================================
// Managed Tool Entry
// ============================================================================

/** A tool record enriched with lifecycle and policy state. */
export interface ManagedTool {
  name: string;
  enabled: boolean;
  policy: ToolPolicy;
  stats: ToolUsageStats;
}

// ============================================================================
// Default Policies
// ============================================================================

/**
 * Built-in tools whose handlers touch the local filesystem or shell are
 * flagged as local-only with appropriate permission levels.
 */
const LOCAL_ONLY_TOOLS: Record<string, ToolPolicy> = {
  // Workspace tools that interact with local filesystem
  workspace_create:  { localOnly: true, permission: 'write' },
  workspace_delete:  { localOnly: true, permission: 'write' },
  workspace_sync:    { localOnly: true, permission: 'write' },
  workspace_publish: { localOnly: true, permission: 'write' },
  workspace_status:  { localOnly: true, permission: 'read' },
  workspace_select:  { localOnly: true, permission: 'read' },
  workspace_list:    { localOnly: true, permission: 'read' },
  file_delete:       { localOnly: true, permission: 'write' },
  folder_delete:     { localOnly: true, permission: 'write' },

  // App / runtime tools execute shell commands locally
  app_run:           { localOnly: true, permission: 'execute' },
  app_test:          { localOnly: true, permission: 'execute' },
  browser_test:      { localOnly: true, permission: 'execute' },

  // Workflow / cron tools manage local scheduled processes
  workflow_create:   { localOnly: true, permission: 'write' },
  workflow_run:      { localOnly: true, permission: 'execute' },
  workflow_delete:   { localOnly: true, permission: 'write' },
  cron_create:       { localOnly: true, permission: 'write' },
  cron_delete:       { localOnly: true, permission: 'write' },
  cron_run:          { localOnly: true, permission: 'execute' },
};

/** Default policy for tools not explicitly listed above. */
const DEFAULT_POLICY: ToolPolicy = { localOnly: false, permission: 'read' };

// ============================================================================
// Tool Manager
// ============================================================================

export class ToolManager {
  private static instance: ToolManager | undefined;

  private registry: ToolRegistry;
  private permissionPolicy: PermissionPolicy;

  /** Per-tool lifecycle and stats state. */
  private managed: Map<string, ManagedTool> = new Map();

  private constructor(environment: ExecutionEnvironment = 'local') {
    this.registry = getToolRegistry();
    this.permissionPolicy = new PermissionPolicy(environment);
    this.syncFromRegistry();
  }

  // --------------------------------------------------------------------------
  // Singleton
  // --------------------------------------------------------------------------

  public static getInstance(environment?: ExecutionEnvironment): ToolManager {
    if (!ToolManager.instance) {
      ToolManager.instance = new ToolManager(environment);
    }
    return ToolManager.instance;
  }

  /** Resets singleton (for testing). */
  public static resetInstance(): void {
    ToolManager.instance = undefined;
  }

  // --------------------------------------------------------------------------
  // Environment
  // --------------------------------------------------------------------------

  /** Returns the current execution environment. */
  getEnvironment(): ExecutionEnvironment {
    return this.permissionPolicy.getEnvironment();
  }

  /** Changes the execution environment at runtime. */
  setEnvironment(env: ExecutionEnvironment): void {
    this.permissionPolicy.setEnvironment(env);
    logger.info(`ToolManager: execution environment set to '${env}'`);
  }

  // --------------------------------------------------------------------------
  // Permission Helpers
  // --------------------------------------------------------------------------

  /** Grants a permission level. */
  grantPermission(perm: ToolPermission): void {
    this.permissionPolicy.grant(perm);
  }

  /** Revokes a permission level. */
  revokePermission(perm: ToolPermission): void {
    this.permissionPolicy.revoke(perm);
  }

  // --------------------------------------------------------------------------
  // Registry Sync
  // --------------------------------------------------------------------------

  /**
   * Ensures every tool in the underlying registry has a corresponding
   * managed entry. Called on construction and can be called after custom
   * tools are hot-reloaded.
   */
  syncFromRegistry(): void {
    for (const tool of this.registry.list()) {
      if (!this.managed.has(tool.name)) {
        this.managed.set(tool.name, {
          name: tool.name,
          enabled: true,
          policy: LOCAL_ONLY_TOOLS[tool.name] ?? DEFAULT_POLICY,
          stats: { invocations: 0, successes: 0, failures: 0, totalDurationMs: 0 },
        });
      }
    }

    // Custom tools loaded from JSON files are always local-only + execute.
    for (const tool of this.registry.list()) {
      if (tool.isCustom) {
        const entry = this.managed.get(tool.name);
        if (entry) {
          entry.policy = { localOnly: true, permission: 'execute' };
        }
      }
    }
  }

  // --------------------------------------------------------------------------
  // Enable / Disable
  // --------------------------------------------------------------------------

  /** Enables a previously disabled tool. */
  enable(name: string): boolean {
    const entry = this.managed.get(name);
    if (!entry) return false;
    entry.enabled = true;
    logger.info(`ToolManager: tool '${name}' enabled`);
    return true;
  }

  /** Disables a tool — execute() will reject calls to it. */
  disable(name: string): boolean {
    const entry = this.managed.get(name);
    if (!entry) return false;
    entry.enabled = false;
    logger.info(`ToolManager: tool '${name}' disabled`);
    return true;
  }

  /** Returns true if the tool is currently enabled. */
  isEnabled(name: string): boolean {
    return this.managed.get(name)?.enabled ?? false;
  }

  // --------------------------------------------------------------------------
  // Policy Queries
  // --------------------------------------------------------------------------

  /** Returns the policy for a registered tool, or undefined. */
  getPolicy(name: string): ToolPolicy | undefined {
    return this.managed.get(name)?.policy;
  }

  /** Returns all tools flagged as local-only. */
  getLocalOnlyTools(): ManagedTool[] {
    return Array.from(this.managed.values()).filter((t) => t.policy.localOnly);
  }

  // --------------------------------------------------------------------------
  // Usage Stats
  // --------------------------------------------------------------------------

  /** Returns usage stats for a single tool. */
  getStats(name: string): ToolUsageStats | undefined {
    return this.managed.get(name)?.stats;
  }

  /** Returns stats for all tools, keyed by tool name. */
  getAllStats(): Record<string, ToolUsageStats> {
    const out: Record<string, ToolUsageStats> = {};
    for (const [name, entry] of this.managed) {
      out[name] = { ...entry.stats };
    }
    return out;
  }

  /** Computes the error rate (0–1) for a tool, or 0 if never invoked. */
  getErrorRate(name: string): number {
    const stats = this.managed.get(name)?.stats;
    if (!stats || stats.invocations === 0) return 0;
    return stats.failures / stats.invocations;
  }

  // --------------------------------------------------------------------------
  // Execution
  // --------------------------------------------------------------------------

  /**
   * Validates policy, checks enabled state, then delegates to the underlying
   * ToolRegistry for schema validation and handler invocation.
   */
  async execute(name: string, args: unknown, context?: ToolContext): Promise<ToolResult> {
    // Ensure we have the latest tools from registry
    this.syncFromRegistry();

    const entry = this.managed.get(name);
    if (!entry) {
      return { success: false, output: `Tool '${name}' not found`, duration: 0 };
    }

    // Enabled check
    if (!entry.enabled) {
      return {
        success: false,
        output: `Tool '${name}' is currently disabled`,
        duration: 0,
      };
    }

    // Permission / local-only policy check
    const check = this.permissionPolicy.check(name, entry.policy);
    if (!check.allowed) {
      return { success: false, output: check.reason!, duration: 0 };
    }

    // Delegate to registry (handles schema validation, danger-level, handler)
    const result = await this.registry.execute(name, args, context);

    // Update stats
    entry.stats.invocations++;
    if (result.success) {
      entry.stats.successes++;
    } else {
      entry.stats.failures++;
    }
    entry.stats.totalDurationMs += result.duration;

    return result;
  }

  // --------------------------------------------------------------------------
  // Tool Discovery
  // --------------------------------------------------------------------------

  /**
   * Scans a directory for `.ts` tool handler files and returns discovered
   * file names. This is informational — actual registration is handled by
   * the ToolRegistry's built-in registration and custom-tool watcher.
   */
  discoverToolFiles(directory: string): string[] {
    try {
      if (!fs.existsSync(directory)) return [];
      const entries = fs.readdirSync(directory, { withFileTypes: true });
      return entries
        .filter((e) => e.isFile() && (e.name.endsWith('.ts') || e.name.endsWith('.json')))
        .filter((e) => !['types.ts', 'index.ts', 'registry.ts', 'loader.ts', 'manager.ts'].includes(e.name))
        .map((e) => path.join(directory, e.name));
    } catch (err) {
      logger.error('ToolManager: discovery scan failed', err);
      return [];
    }
  }

  // --------------------------------------------------------------------------
  // Listing
  // --------------------------------------------------------------------------

  /** Returns all managed tool entries. */
  listManaged(): ManagedTool[] {
    this.syncFromRegistry();
    return Array.from(this.managed.values());
  }
}

export const getToolManager = (env?: ExecutionEnvironment) => ToolManager.getInstance(env);

