/**
 * @fileoverview Tool Manager Unit Tests
 *
 * Tests the ToolManager class: enable/disable, usage tracking,
 * local-only policy enforcement, and tool discovery.
 */

import { describe, it, expect, beforeEach } from 'vitest';
import { ToolManager } from '../../src/tools/manager.js';

describe('Tool Manager', () => {
  beforeEach(() => {
    ToolManager.resetInstance();
  });

  describe('Singleton', () => {
    it('should return the same instance', () => {
      const a = ToolManager.getInstance();
      const b = ToolManager.getInstance();
      expect(a).toBe(b);
    });

    it('should allow reset for testing', () => {
      const a = ToolManager.getInstance();
      ToolManager.resetInstance();
      const b = ToolManager.getInstance();
      expect(a).not.toBe(b);
    });
  });

  describe('Environment', () => {
    it('should default to local environment', () => {
      const mgr = ToolManager.getInstance();
      expect(mgr.getEnvironment()).toBe('local');
    });

    it('should allow changing environment', () => {
      const mgr = ToolManager.getInstance();
      mgr.setEnvironment('cloud');
      expect(mgr.getEnvironment()).toBe('cloud');
    });
  });

  describe('Enable / Disable', () => {
    it('should disable a tool', () => {
      const mgr = ToolManager.getInstance();
      expect(mgr.isEnabled('workspace_list')).toBe(true);
      expect(mgr.disable('workspace_list')).toBe(true);
      expect(mgr.isEnabled('workspace_list')).toBe(false);
    });

    it('should re-enable a tool', () => {
      const mgr = ToolManager.getInstance();
      mgr.disable('workspace_list');
      expect(mgr.enable('workspace_list')).toBe(true);
      expect(mgr.isEnabled('workspace_list')).toBe(true);
    });

    it('should return false for unknown tool', () => {
      const mgr = ToolManager.getInstance();
      expect(mgr.disable('nonexistent_tool')).toBe(false);
      expect(mgr.enable('nonexistent_tool')).toBe(false);
    });

    it('should block execution of disabled tools', async () => {
      const mgr = ToolManager.getInstance();
      mgr.disable('workspace_list');
      const result = await mgr.execute('workspace_list', {});
      expect(result.success).toBe(false);
      expect(result.output).toContain('disabled');
    });
  });

  describe('Local-Only Policy', () => {
    it('should flag workspace tools as local-only', () => {
      const mgr = ToolManager.getInstance();
      const policy = mgr.getPolicy('workspace_create');
      expect(policy).toBeDefined();
      expect(policy!.localOnly).toBe(true);
      expect(policy!.permission).toBe('write');
    });

    it('should flag app_run as local-only execute', () => {
      const mgr = ToolManager.getInstance();
      const policy = mgr.getPolicy('app_run');
      expect(policy).toBeDefined();
      expect(policy!.localOnly).toBe(true);
      expect(policy!.permission).toBe('execute');
    });

    it('should not flag web tools as local-only', () => {
      const mgr = ToolManager.getInstance();
      const policy = mgr.getPolicy('web_fetch');
      expect(policy).toBeDefined();
      expect(policy!.localOnly).toBe(false);
    });

    it('should list all local-only tools', () => {
      const mgr = ToolManager.getInstance();
      const localTools = mgr.getLocalOnlyTools();
      expect(localTools.length).toBeGreaterThan(0);
      for (const t of localTools) {
        expect(t.policy.localOnly).toBe(true);
      }
    });

    it('should block local-only tools in cloud environment', async () => {
      const mgr = ToolManager.getInstance('local');
      mgr.setEnvironment('cloud');
      const result = await mgr.execute('workspace_create', { name: 'test' });
      expect(result.success).toBe(false);
      expect(result.output).toContain('local-only');
    });

    it('should allow local-only tools in local environment', async () => {
      const mgr = ToolManager.getInstance('local');
      // workspace_list doesn't need args, but schema validation may fail —
      // we just want to confirm it passes the policy check (not blocked by env).
      const result = await mgr.execute('workspace_list', {});
      // It should pass the policy layer (may still fail in handler — that's fine)
      expect(result.output).not.toContain('local-only');
    });

    it('should block tools when required permission is revoked', async () => {
      const mgr = ToolManager.getInstance('local');
      mgr.revokePermission('write');
      const result = await mgr.execute('workspace_create', { name: 'test' });
      expect(result.success).toBe(false);
      expect(result.output).toContain('permission');
    });
  });

  describe('Usage Stats', () => {
    it('should start with zero stats', () => {
      const mgr = ToolManager.getInstance();
      const stats = mgr.getStats('workspace_list');
      expect(stats).toBeDefined();
      expect(stats!.invocations).toBe(0);
      expect(stats!.successes).toBe(0);
      expect(stats!.failures).toBe(0);
    });

    it('should track invocations after execute', async () => {
      const mgr = ToolManager.getInstance();
      await mgr.execute('workspace_list', {});
      const stats = mgr.getStats('workspace_list');
      expect(stats!.invocations).toBe(1);
    });

    it('should compute error rate', async () => {
      const mgr = ToolManager.getInstance();
      // Execute with bad args to trigger validation failure (counts as failure)
      await mgr.execute('workspace_create', { bad_key: true });
      const rate = mgr.getErrorRate('workspace_create');
      expect(rate).toBe(1); // 1 failure / 1 invocation
    });

    it('should return 0 error rate for never-invoked tools', () => {
      const mgr = ToolManager.getInstance();
      expect(mgr.getErrorRate('ask_user')).toBe(0);
    });

    it('should return all stats', () => {
      const mgr = ToolManager.getInstance();
      const all = mgr.getAllStats();
      expect(Object.keys(all).length).toBeGreaterThan(0);
    });
  });

  describe('Tool Discovery', () => {
    it('should discover tool files in src/tools', () => {
      const mgr = ToolManager.getInstance();
      const toolsDir = new URL('../../src/tools', import.meta.url).pathname;
      const files = mgr.discoverToolFiles(toolsDir);
      expect(files.length).toBeGreaterThan(0);
      // Should find handler files like workspace.ts, task.ts, etc.
      expect(files.some((f) => f.endsWith('workspace.ts'))).toBe(true);
    });

    it('should return empty array for nonexistent directory', () => {
      const mgr = ToolManager.getInstance();
      const files = mgr.discoverToolFiles('/tmp/nonexistent_tool_dir');
      expect(files).toEqual([]);
    });

    it('should exclude infrastructure files', () => {
      const mgr = ToolManager.getInstance();
      const toolsDir = new URL('../../src/tools', import.meta.url).pathname;
      const files = mgr.discoverToolFiles(toolsDir);
      const basenames = files.map((f) => f.split('/').pop());
      expect(basenames).not.toContain('types.ts');
      expect(basenames).not.toContain('index.ts');
      expect(basenames).not.toContain('registry.ts');
      expect(basenames).not.toContain('loader.ts');
      expect(basenames).not.toContain('manager.ts');
    });
  });

  describe('Listing', () => {
    it('should list all managed tools', () => {
      const mgr = ToolManager.getInstance();
      const tools = mgr.listManaged();
      expect(tools.length).toBeGreaterThanOrEqual(40);
      for (const t of tools) {
        expect(t).toHaveProperty('name');
        expect(t).toHaveProperty('enabled');
        expect(t).toHaveProperty('policy');
        expect(t).toHaveProperty('stats');
      }
    });
  });
});

