/**
 * @fileoverview Permission Policy Unit Tests
 *
 * Tests the PermissionPolicy class for local-only enforcement
 * and permission-level gating.
 */

import { describe, it, expect } from 'vitest';
import { PermissionPolicy } from '../../src/security/permissions.js';
import type { ToolPolicy } from '../../src/tools/types.js';

describe('PermissionPolicy', () => {
  describe('Environment', () => {
    it('should default to local', () => {
      const p = new PermissionPolicy();
      expect(p.getEnvironment()).toBe('local');
    });

    it('should accept cloud environment', () => {
      const p = new PermissionPolicy('cloud');
